package sessions

import (
	"errors"
	"time"

	"github.com/essentialkaos/branca/v2"
)

type Store interface {
	// EncryptCookie encrypts the given plaintext and produces a string that can be
	// safely stored in an HTTP cookie.
	EncryptCookie(plaintext []byte) (cookie string, err error)

	// DecryptCookie decodes a cookie generated by `EncryptCookie` and returns
	// the original binary plaintext.
	DecryptCookie(cookie string, maxAge time.Duration) (plaintext []byte, err error)

	EncryptSession(session Session) (cookie string, err error)
	DecryptSession(cookie string, maxAge time.Duration) (session Session, err error)
}

var ErrTokenExpired = errors.New("token is expired")
var ErrAllZeroKey = errors.New("the provided session encryption key must not be all zeroes")

type store struct {
	signer branca.Branca
}

var _ Store = &store{}

func NewStore(key []byte) (Store, error) {
	if err := expectNonZeroKey(key); err != nil {
		return nil, err
	}

	signer, err := branca.NewBranca(key)
	if err != nil {
		return nil, err
	}

	return &store{signer: signer}, nil
}

func (s *store) EncryptCookie(payload []byte) (cookie string, err error) {
	return s.signer.EncodeToString(payload)
}

func (s *store) DecryptCookie(cookie string, maxAge time.Duration) (plaintext []byte, err error) {
	token, err := s.signer.DecodeString(cookie)
	if err != nil {
		return nil, err
	}

	if token.IsExpired(uint32(maxAge / time.Second)) {
		return nil, ErrTokenExpired
	}

	return token.Payload(), nil
}

func (s *store) EncryptSession(session Session) (cookie string, err error) {
	payload, err := session.Serialize()
	if err != nil {
		return "", err
	}

	return s.EncryptCookie(payload)
}

func (s *store) DecryptSession(cookie string, maxAge time.Duration) (session Session, err error) {
	payload, err := s.DecryptCookie(cookie, maxAge)
	if err != nil {
		return nil, err
	}

	return decodeSession(payload)
}

func expectNonZeroKey(key []byte) error {
	for _, b := range key {
		if b != 0 {
			return nil
		}
	}
	return ErrAllZeroKey
}
